<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Database, FileUp, Pencil, Plus, Save, Trash2, X } from 'lucide-vue-next'
import AdminModuleHeader from '../components/AdminModuleHeader.vue'
import { api } from '../api'

type City = { id: number; name: string }
type Attraction = { id: number; city_id: number; city_name: string; name: string }
type Ranking = { id: number; ranking_type: 'city' | 'attraction'; city_id: number | null; attraction_id: number | null; target_name: string; rank: number; score: number; reason: string; is_active: boolean }
const rankingType = ref<'city' | 'attraction'>('city'); const cities = ref<City[]>([]); const attractions = ref<Attraction[]>([]); const entries = ref<Ranking[]>([]); const error = ref(''); const notice = ref(''); const editing = ref<Ranking | null>(null); const showImport = ref(false)
const form = ref({ target_id: 0, rank: 1, score: 80, reason: '管理员维护', is_active: true })
const importText = ref('[\n  { "ranking_type": "city", "city_id": 1, "rank": 1, "score": 95, "reason": "内容完整、用户反馈良好" }\n]')
const targets = computed(() => rankingType.value === 'city' ? cities.value : attractions.value)
async function load() { [cities.value, attractions.value, entries.value] = await Promise.all([api<City[]>('/admin/cities'), api<Attraction[]>('/admin/attractions'), api<Ranking[]>(`/admin/rankings?ranking_type=${rankingType.value}`)]) }
function chooseType(value: 'city' | 'attraction') { rankingType.value = value; editing.value = null; form.value = { target_id: 0, rank: 1, score: 80, reason: '管理员维护', is_active: true }; void load() }
function edit(item?: Ranking) { editing.value = item ?? null; form.value = item ? { target_id: item.ranking_type === 'city' ? item.city_id || 0 : item.attraction_id || 0, rank: item.rank, score: item.score, reason: item.reason, is_active: item.is_active } : { target_id: 0, rank: 1, score: 80, reason: '管理员维护', is_active: true }; notice.value = '' }
async function save() { try { if (!editing.value && !form.value.target_id) throw new Error('请选择排行对象'); const path = editing.value ? `/admin/rankings/${editing.value.id}` : '/admin/rankings'; const body = editing.value ? { rank: form.value.rank, score: form.value.score, reason: form.value.reason, is_active: form.value.is_active } : { ranking_type: rankingType.value, rank: form.value.rank, score: form.value.score, reason: form.value.reason, is_active: form.value.is_active, ...(rankingType.value === 'city' ? { city_id: form.value.target_id } : { attraction_id: form.value.target_id }) }; await api(path, { method: editing.value ? 'PATCH' : 'POST', body: JSON.stringify(body) }); await load(); edit(); notice.value = '排行记录已保存' } catch (exception) { notice.value = exception instanceof Error ? exception.message : '保存失败' } }
async function remove(item: Ranking) { if (!window.confirm(`确定删除“${item.target_name}”的排行记录吗？`)) return; try { await api(`/admin/rankings/${item.id}`, { method: 'DELETE' }); await load(); notice.value = '排行记录已删除' } catch (exception) { notice.value = exception instanceof Error ? exception.message : '删除失败' } }
async function importItems() { try { const items = JSON.parse(importText.value); if (!Array.isArray(items)) throw new Error('导入内容必须是 JSON 数组'); await api('/admin/rankings/import', { method: 'POST', body: JSON.stringify({ items }) }); await load(); notice.value = `已导入 ${items.length} 条排行`; showImport.value = false } catch (exception) { notice.value = exception instanceof Error ? exception.message : '导入失败' } }
onMounted(async () => { try { await load() } catch (exception) { error.value = exception instanceof Error ? exception.message : '加载失败' } })
</script>

<template><div class="page-container"><AdminModuleHeader eyebrow="CURATED RANKINGS" title="排行管理" description="维护前台城市和景点排行榜；启用记录会优先覆盖自动计算结果。" /><div v-if="error" class="empty-state"><Database :size="28" /><h2>{{ error }}</h2></div><template v-else><div class="admin-toolbar"><div class="admin-toolbar-group"><button :class="['admin-filter-button', { active: rankingType === 'city' }]" @click="chooseType('city')">城市排行</button><button :class="['admin-filter-button', { active: rankingType === 'attraction' }]" @click="chooseType('attraction')">景点排行</button></div><div class="admin-toolbar-group"><button class="secondary-button" @click="showImport = !showImport"><FileUp :size="16" />批量导入</button><button class="primary-button" @click="edit()"><Plus :size="16" />新增排行</button></div></div><p v-if="notice" class="admin-notice">{{ notice }}</p><section class="admin-editor"><div class="admin-editor-heading"><h2>{{ editing ? '编辑排行记录' : '新增排行记录' }}</h2><button class="admin-table-action" title="关闭编辑" @click="edit()"><X :size="16" /></button></div><div class="admin-form-grid"><label>排行对象<select v-model.number="form.target_id" :disabled="Boolean(editing)"><option :value="0" disabled>选择对象</option><option v-for="target in targets" :key="target.id" :value="target.id">{{ target.name }}<template v-if="'city_name' in target"> · {{ target.city_name }}</template></option></select></label><label>名次<input v-model.number="form.rank" type="number" min="1" /></label><label>评分<input v-model.number="form.score" type="number" min="0" max="100" /></label><label>上榜原因<input v-model="form.reason" /></label><label class="admin-check"><input v-model="form.is_active" type="checkbox" />在前台展示</label></div><button class="primary-button" @click="save"><Save :size="16" />保存排行</button></section><section v-if="showImport" class="admin-editor"><div class="admin-editor-heading"><h2>批量导入排行</h2><button class="admin-table-action" title="关闭导入" @click="showImport = false"><X :size="16" /></button></div><textarea v-model="importText" class="admin-json-input" rows="10" aria-label="排行 JSON 导入内容" /><button class="primary-button" @click="importItems"><FileUp :size="16" />导入 JSON</button></section><div class="admin-table-wrap"><table class="admin-data-table"><thead><tr><th>名次</th><th>对象</th><th>评分</th><th>上榜原因</th><th>状态</th><th aria-label="操作"></th></tr></thead><tbody><tr v-for="item in entries" :key="item.id"><td><strong>#{{ item.rank }}</strong></td><td>{{ item.target_name }}</td><td>{{ item.score }}</td><td>{{ item.reason }}</td><td><span :class="['admin-status', { muted: !item.is_active }]">{{ item.is_active ? '已展示' : '未展示' }}</span></td><td class="admin-table-actions"><button class="admin-table-action" title="编辑排行" @click="edit(item)"><Pencil :size="16" /></button><button class="admin-table-action danger-action" title="删除排行" @click="remove(item)"><Trash2 :size="16" /></button></td></tr></tbody></table><div v-if="!entries.length" class="admin-page-empty"><p>暂时没有手工排行记录</p></div></div></template></div></template>
